//! Identity-preserving checked Attr transfer into inert Element sources.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><div id=mount></div><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://inert-attachment.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}
#[test]
fn inert_attribute_attachment_same_identity_replacement_removal_values_documents_and_observers(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var owner=document.implementation.createHTMLDocument('owner'),other=document.implementation.createDocument(null,''),node=owner.createElement('span'),a=other.createAttribute('data-note'),watch=new MutationObserver(function(){}),map=node.attributes;watch.observe(node,{attributes:true,attributeOldValue:true});a.value='\ud800';if(node.setAttributeNode(a)!==null||a.ownerElement!==node||a.ownerDocument!==owner||node.getAttributeNode('data-note')!==a||map[0]!==a||map.length!==1||node.getAttribute('data-note').charCodeAt(0)!==0xd800)throw 'genuine inert attachment';
var records=watch.takeRecords();if(records.length!==1||records[0].target!==node||records[0].oldValue!==null||records[0].attributeName!=='data-note')throw 'new attachment observation';
var b=other.createAttribute('data-note');b.value='second';if(node.setAttributeNodeNS(b)!==a||a.ownerElement!==null||a.ownerDocument!==owner||a.value.charCodeAt(0)!==0xd800||b.ownerElement!==node||b.ownerDocument!==owner||node.getAttributeNode('data-note')!==b||map[0]!==b||map.length!==1)throw 'replaced actual Attr identity and value';records=watch.takeRecords();if(records.length!==1||records[0].oldValue.charCodeAt(0)!==0xd800)throw 'replacement old units';
if(node.setAttributeNode(b)!==b||watch.takeRecords().length)throw 'same identity no extra record';b.value='third';records=watch.takeRecords();if(records.length!==1||records[0].oldValue!=='second'||node.getAttribute('data-note')!=='third')throw 'attached setter shares real inert source';if(node.removeAttributeNode(b)!==b||b.ownerElement!==null||b.ownerDocument!==owner||b.value!=='third'||map.length||node.getAttributeNode('data-note')!==null)throw 'same removal identity';records=watch.takeRecords();if(records.length!==1||records[0].oldValue!=='third')throw 'removal old value';
"#);
}
#[test]
fn inert_attribute_attachment_namespace_prefix_replacement_foreign_owner_and_xml_case_are_actual(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument('urn:element','e:Root'),node=xml.documentElement,other=document.implementation.createHTMLDocument('other'),a=other.createAttributeNS('urn:attribute','p:Case');a.value='first';if(node.setAttributeNodeNS(a)!==null||node.getAttributeNodeNS('urn:attribute','Case')!==a||a.ownerDocument!==xml||a.ownerElement!==node||a.name!=='p:Case')throw 'actual foreign element attribute';
var b=other.createAttributeNS('urn:attribute','q:Case');b.value='second';if(node.setAttributeNode(b)!==a||node.attributes.length!==1||node.attributes[0]!==b||b.name!=='q:Case'||b.prefix!=='q'||a.name!=='p:Case'||a.value!=='first'||a.ownerElement!==null||a.ownerDocument!==xml||node.getAttributeNodeNS('urn:attribute','Case')!==b)throw 'expanded-name replacement changes QName without rewriting old Attr';b.value='changed';if(node.getAttributeNodeNS('urn:attribute','Case').value!=='changed')throw 'foreign attached value remains genuine data';
var htmlNS='http://www.w3.org/1999/xhtml',element=xml.createElementNS(htmlNS,'div'),mixed=xml.createAttribute('MiXeD');mixed.value='case';element.setAttributeNode(mixed);if(element.getAttribute('MiXeD')!=='case'||element.getAttribute('mixed')!==null||element.getAttributeNode('MiXeD')!==mixed||element.getAttributeNode('mixed')!==null)throw 'XML owner preserves HTML namespace attribute case';element.setAttribute('OtHeR','value');if(element.getAttribute('OtHeR')!=='value'||element.getAttribute('other')!==null)throw 'ordinary setter uses actual owner kind';
var node2=xml.createElementNS(htmlNS,'Other');node2.setAttribute('data-old','raw');var replacement=other.createAttribute('data-old');replacement.value='new';var previous=node2.setAttributeNode(replacement);if(!(previous instanceof Attr)||previous.ownerElement!==null||previous.ownerDocument!==xml||previous.name!=='data-old'||previous.value!=='raw'||node2.getAttributeNode('data-old')!==replacement||replacement.ownerDocument!==xml)throw 'uncached replaced Attr is real';
"#);
}
#[test]
fn inert_attribute_attachment_canonical_brands_inuse_and_missing_removal_have_no_prefix(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var owner=document.implementation.createHTMLDocument('owner'),a=owner.createElement('span'),b=owner.createElement('div'),attr=owner.createAttribute('data-note'),method=Element.prototype.setAttributeNode,calls=0;if(method.length!==1||method.name!=='setAttributeNode'||a.setAttributeNode!==method||a.removeAttributeNode!==Element.prototype.removeAttributeNode)throw 'canonical inert member';a.setAttributeNode(attr);var caught=false;try{b.setAttributeNode(attr);}catch(e){caught=e instanceof DOMException&&e.name==='InUseAttributeError';}if(!caught||attr.ownerElement!==a||b.attributes.length)throw 'typed in-use no prefix';caught=false;try{b.removeAttributeNode(attr);}catch(e){caught=e instanceof DOMException&&e.name==='NotFoundError';}if(!caught||attr.ownerElement!==a)throw 'typed notfound';caught=false;try{method.call({}, {toString:function(){calls++;return 'fake';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls||a.getAttributeNode('data-note')!==attr)throw 'brand before author code';
var image=owner.createElement('img'),src=owner.createAttribute('src');src.value='https://no-inert-attachment.test/image.png';if(image.setAttributeNode(src)!==null||src.ownerElement!==image||src.ownerDocument!==owner||image.getAttribute('src')!==src.value)throw 'resource attribute stays legal inert data';caught=false;try{document.getElementById('mount').appendChild(image);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||image.ownerDocument!==owner||image.parentNode!==null||src.ownerElement!==image)throw 'data attachment cannot authorize activation';
"#);assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());let(a,b,c)=page.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());
}

#[test]
fn inert_attribute_attachment_saved_realm_revalidates_origin_before_conversion_or_transfer(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var owner=document.implementation.createHTMLDocument('owner'),target=owner.createElement('span'),attr=owner.createAttribute('data-note'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,saved=w.Element.prototype.setAttributeNode,read=w.Element.prototype.getAttributeNode,order='',name={toString:function(){order+='n';return 'data-note';}};if(saved===Element.prototype.setAttributeNode||Object.getPrototypeOf(saved)!==w.Function.prototype||saved.call(target,attr)!==null||read.call(target,name)!==attr||order!=='n')throw 'genuine child realm Element methods';target.removeAttributeNode(attr);
"#);page.set_location(&crate::navigation::address("https://other-inert-attachment.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.attributes.len(),page.state.dom_commits);for expression in ["saved.call(target,attr);","read.call(target,name);"]{assert_eq!(page.console_eval(&mut doc,&mut forms,expression).errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.attributes.len(),page.state.dom_commits),before);}run(&mut doc,&mut forms,&mut page,"if(order!=='n'||attr.ownerElement!==null||target.attributes.length)throw 'origin guard before conversion or mutation';");
}
